inner_command:
set -e
cd /home/agent/audit
cat > /tmp/curves_audit_check.js <<'EOF'
const hre = require('hardhat');
const { ethers } = hre;
async function main() {
  const [owner, friend] = await ethers.getSigners();
  const F = await ethers.getContractFactory('CurvesERC20Factory');
  const f = await F.deploy();
  const S = await ethers.getContractFactory('FeeSplitter');
  const s = await S.deploy();
  const C = await ethers.getContractFactory('Curves');
  const c = await C.deploy(f.address, s.address);
  await s.setCurves(c.address);
  await s.setManager(c.address, true);
  const protocolFee = ethers.utils.parseEther('0');
  const subjectFee = ethers.utils.parseEther('0');
  const referralFee = ethers.utils.parseEther('0');
  const holdersFee = ethers.utils.parseEther('0.1');
  await c.setMaxFeePercent(protocolFee.add(subjectFee).add(referralFee).add(holdersFee));
  await c.setProtocolFeePercent(protocolFee, owner.address);
  await c.setExternalFeePercent(subjectFee, referralFee, holdersFee);
  await c.buyCurvesToken(owner.address, 1);
  let buyPrice = await c.getBuyPrice(owner.address, 1);
  let totalPayment = buyPrice.add(buyPrice.mul(holdersFee).div(ethers.utils.parseEther('1')));
  await c.connect(friend).buyCurvesToken(owner.address, 1, {value: totalPayment});
  console.log('claim owner before transfer', (await s.getClaimableFees(owner.address, owner.address)).toString());
  await c.connect(friend).transferCurvesToken(owner.address, owner.address, 1);
  console.log('balances after transfer',
    (await c.curvesTokenBalance(owner.address, owner.address)).toString(),
    (await c.curvesTokenBalance(owner.address, friend.address)).toString());
  buyPrice = await c.getBuyPrice(owner.address, 1);
  totalPayment = buyPrice.add(buyPrice.mul(holdersFee).div(ethers.utils.parseEther('1')));
  await c.connect(friend).buyCurvesToken(owner.address, 1, {value: totalPayment});
  console.log('claim owner after transfer+fee', (await s.getClaimableFees(owner.address, owner.address)).toString());
  console.log('claim friend after transfer+fee', (await s.getClaimableFees(owner.address, friend.address)).toString());
}
main().then(()=>process.exit(0)).catch((e)=>{console.error(e);process.exit(1)});
EOF
