cd /home/agent/audit && cat > /tmp/upgrade_check.t.sol <<'EOF'
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;
import {Test} from 'forge-std/Test.sol';
import {WellUpgradeable} from 'src/WellUpgradeable.sol';
import {IERC20} from 'oz/token/ERC20/IERC20.sol';
import {Aquifer} from 'src/Aquifer.sol';
import {ConstantProduct2} from 'src/functions/ConstantProduct2.sol';
import {LibWellUpgradeableConstructor} from 'src/libraries/LibWellUpgradeableConstructor.sol';
import {ERC1967Proxy} from 'oz/proxy/ERC1967/ERC1967Proxy.sol';
import {Call} from 'src/interfaces/IWell.sol';
import {MockToken} from 'mocks/tokens/MockToken.sol';
import {MockPump} from 'mocks/pumps/MockPump.sol';

contract T is Test {
    function testCheck() public {
        IERC20[] memory toks = new IERC20[](2);
        toks[0] = IERC20(address(new MockToken('A','A',18)));
        toks[1] = IERC20(address(new MockToken('B','B',18)));
        Call memory wf = Call(address(new ConstantProduct2()), abi.encode('x'));
        Call[] memory ps = new Call[](1);
        ps[0] = Call(address(new MockPump()), abi.encode('y'));
        Aquifer aq = new Aquifer();
        address impl = address(new WellUpgradeable());
        (bytes memory imm, bytes memory initData) = LibWellUpgradeableConstructor.encodeWellDeploymentData(address(aq), toks, wf, ps);
        address bored = aq.boreWell(impl, imm, initData, bytes32(0));
        address owner = address(0xBEEF);
        vm.prank(owner);
        ERC1967Proxy proxy = new ERC1967Proxy(bored, LibWellUpgradeableConstructor.encodeWellInitFunctionCall(toks, wf));
        vm.prank(owner);
        vm.expectRevert();
        WellUpgradeable(address(proxy)).upgradeTo(bored);
    }
}
EOF
forge test --match-path /tmp/upgrade_check.t.sol -vv

