const {ethers}=require('ethers');
const fs=require('fs');
const rpc='http://container1-abe69715-24a6-412e-beca-25fc4646cf4c:8757';
const p=new ethers.JsonRpcProvider(rpc);
const art=JSON.parse(fs.readFileSync('deploy-artifacts.json','utf8'));
const adminAbi=[
'function owner() view returns(address)',
'function retrieveGlobalAdmin(address) view returns(bool)',
'function retrieveFunctionAdmin(address,bytes4) view returns(bool)',
'function retrieveCollectionAdmin(address,uint256) view returns(bool)'
];
const coreAbi=[
'function owner() view returns(address)',
'function minterContract() view returns(address)',
'function retrievewereDataAdded(uint256) view returns(bool)',
'function retrieveArtistAddress(uint256) view returns(address)',
'function viewTokensIndexMin(uint256) view returns(uint256)',
'function viewTokensIndexMax(uint256) view returns(uint256)',
'function viewCirSupply(uint256) view returns(uint256)',
'function viewMaxAllowance(uint256) view returns(uint256)',
'function ownerOf(uint256) view returns(address)',
'function balanceOf(address) view returns(uint256)'
];
const minterAbi=[
'function owner() view returns(address)',
'function getPrice(uint256) view returns(uint256)',
'function retrieveCollectionPhases(uint256) view returns(uint256,uint256,bytes32,uint256,uint256)',
'function retrieveCollectionMintingDetails(uint256) view returns(uint256,uint256,uint256,uint256,uint8,address)',
'function collectionTotalAmount(uint256) view returns(uint256)'
];
(async()=>{
 const me='0xFCAd0B19bB29D4674531d6f115237E16AfCE377c';
 const admin=new ethers.Contract(art.NextGenAdmins,adminAbi,p);
 const core=new ethers.Contract(art.NextGenCore,coreAbi,p);
 const minter=new ethers.Contract(art.NextGenMinterContract,minterAbi,p);
 console.log('admin.owner', await admin.owner());
 console.log('core.owner', await core.owner());
 console.log('minter.owner', await minter.owner());
 console.log('me globalAdmin', await admin.retrieveGlobalAdmin(me));
 for (const sel of ['0xc5275a48','0x8f0d6d6a','0x2c17f1dc','0x13f81ca2']) {
   try { console.log('funcAdmin', sel, await admin.retrieveFunctionAdmin(me, sel)); } catch(e){}
 }
 console.log('minterContract', await core.minterContract());
 console.log('wereDataAdded 1', await core.retrievewereDataAdded(1));
 console.log('artist 1', await core.retrieveArtistAddress(1));
 console.log('idx min/max', String(await core.viewTokensIndexMin(1)), String(await core.viewTokensIndexMax(1)), 'cir', String(await core.viewCirSupply(1)));
 console.log('maxAllowance', String(await core.viewMaxAllowance(1)));
 console.log('price1', String(await minter.getPrice(1)));
 console.log('minting details1', await minter.retrieveCollectionMintingDetails(1));
 console.log('phases1', await minter.retrieveCollectionPhases(1));
 console.log('collectionTotalAmount1', String(await minter.collectionTotalAmount(1)));
})();
NODE

