inner_command:
cd /home/agent/audit/hardhat && node <<'NODE'
const {ethers}=require('ethers');
const fs=require('fs');
const rpc='http://container1-abe69715-24a6-412e-beca-25fc4646cf4c:8757';
const p=new ethers.JsonRpcProvider(rpc);
const art=JSON.parse(fs.readFileSync('deploy-artifacts.json','utf8'));
const abi=[
'event RegisterDelegation(address indexed from, address indexed collectionAddress, address indexed delegationAddress, uint256 useCase, bool allTokens, uint256 _tokenId)',
'event RegisterDelegationUsingSubDelegation(address indexed delegator, address from, address indexed collectionAddress, address indexed delegationAddress, uint256 useCase, bool allTokens, uint256 _tokenId)',
'event RevokeDelegation(address indexed from, address indexed collectionAddress, address indexed delegationAddress, uint256 useCase)',
'event RevokeDelegationUsingSubDelegation(address indexed delegator, address from, address indexed collectionAddress, address indexed delegationAddress, uint256 useCase)',
'function retrieveGlobalStatusOfDelegation(address,address,address,uint256) view returns(bool)',
'function retrieveActiveDelegators(address,address,uint256,uint256) view returns(address[])',
'function retrieveDelegators(address,address,uint256) view returns(address[])',
'function globalDelegationHashes(bytes32,uint256) view returns(address,address,uint256,uint256,bool,uint256)'
];
(async()=>{
 const c=new ethers.Contract(art.DelegationManagementContract,abi,p);
 const latest=await p.getBlockNumber();
 for (const ev of ['RegisterDelegation','RegisterDelegationUsingSubDelegation','RevokeDelegation','RevokeDelegationUsingSubDelegation']) {
   const logs=await c.queryFilter(c.filters[ev](),0,latest);
   console.log('\nEVENT',ev,'count',logs.length);
   for (const l of logs.slice(0,20)) {
     console.log(ev,l.args);
   }
 }
})();
NODE

