const {ethers}=require('ethers');
const fs=require('fs');
const rpc='http://container1-abe69715-24a6-412e-beca-25fc4646cf4c:8757';
const p=new ethers.JsonRpcProvider(rpc);
const ifaces=[
 new ethers.Interface(require('./artifacts/contracts/NextGenAdmins.sol/NextGenAdmins.json').abi),
 new ethers.Interface(require('./artifacts/contracts/NextGenCore.sol/NextGenCore.json').abi),
 new ethers.Interface(require('./artifacts/contracts/MinterContract.sol/NextGenMinterContract.json').abi)
];
(async()=>{
 const txs=['0x46a82f1f01e5f2fb06af6d3d13a918fd78eb1aee912268bde887276a62a398a9','0xf251a0582bbf51fba40c0f513681fe312960683269be2a86d4036bef04715a9d','0x92262aae0b06a2854be5a44f0c930bbcbdde50c1949ce7fc677fdeb5501ccf82','0x7afaefac48a6db5079b15d4e7a99c1b5a652e82a79d8437074723910a0c3fd1a','0x123c4adf51b0a4d14534f62991a6e4bc230101ae4f2cf4c18f9938782176d191','0x7ab91c1e3c23ac837644cd56db26614ca197378ad2af1a86874002d8379274df','0x58d17f6ea2676bf604ff7e8156de4476fa95de5db2d98fb06a8ba3e66f192d01'];
 for (const h of txs){
   const tx=await p.getTransaction(h);
   console.log('\nTX',h,'to',tx.to);
   let done=false;
   for (const iface of ifaces){
     try { const parsed=iface.parseTransaction({data:tx.data,value:tx.value}); console.log(parsed.name, parsed.args); done=true; break;} catch(e){}
   }
   if(!done) console.log('unknown', tx.data);
 }
})();
