date +%s && cd /home/agent/audit/hardhat && node <<'NODE'
const {ethers}=require('ethers');
const fs=require('fs');
const art=JSON.parse(fs.readFileSync('deploy-artifacts.json','utf8'));
const rpc='http://container1-abe69715-24a6-412e-beca-25fc4646cf4c:8757';
const p=new ethers.JsonRpcProvider(rpc);
const coreAbi=[
'function ownerOf(uint256) view returns(address)',
'function balanceOf(address) view returns(uint256)',
'function totalSupply() view returns(uint256)',
'function tokenByIndex(uint256) view returns(uint256)',
'function tokenData(uint256) view returns(string)',
'function viewCirSupply(uint256) view returns(uint256)'
];
const minterAbi=['function getPrice(uint256) view returns(uint256)','function retrieveCollectionPhases(uint256) view returns(uint,uint,bytes32,uint,uint)'];
(async()=>{
 const core=new ethers.Contract(art.NextGenCore,coreAbi,p);
 const minter=new ethers.Contract(art.NextGenMinterContract,minterAbi,p);
 console.log('totalSupply', String(await core.totalSupply()));
 console.log('cirSupply', String(await core.viewCirSupply(1)));
 console.log('price', String(await minter.getPrice(1)));
 console.log('phases', await minter.retrieveCollectionPhases(1));
 const ts=await core.totalSupply();
 for(let i=0n;i<ts;i++){
   const tid=await core.tokenByIndex(i);
   console.log('token', String(tid), 'owner', await core.ownerOf(tid), 'data', await core.tokenData(tid));
 }
})();
NODE

